package com.edufun.portal.model;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="curriculum_versions") public class CurriculumVersion { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String academicYear; private String label; private String sourceUrl; private boolean experimental; private String status="ACTIVE"; private LocalDateTime createdAt=LocalDateTime.now(); public Long getId(){return id;} public String getAcademicYear(){return academicYear;} public void setAcademicYear(String v){academicYear=v;} public String getLabel(){return label;} public void setLabel(String v){label=v;} public String getSourceUrl(){return sourceUrl;} public void setSourceUrl(String v){sourceUrl=v;} public boolean isExperimental(){return experimental;} public void setExperimental(boolean v){experimental=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;} }
